    if (fallbackCollectionSize === 0) {
      console.log("No Landsat 5 TOA images found either.");
      console.log("C1");
      return;
    } else {
      console.log(`Landsat 5 TOA Images: ${fallbackCollectionSize}`);
    }
  } else {
    console.log(`Landsat 5 SR Images: ${collectionSize}`);
  }

  // Take the median of the collection to get a single image, then clip
  const image = collection.median().clip(aoi);

  // Check if the resulting image is valid (has any bands)
  if (!image || image.bandNames().length().getInfo() === 0) {
    console.log("Resulting image is empty after median composite.");
    console.log("C3"); // Indicates an issue in image creation
    return;
  }

  // 3. Processing - Define Land and River Areas
  // Use JRC Global Surface Water to define water bodies.
  // We'll use the 'occurrence' band for water.
  const water_threshold = 0.5; // Pixels with water occurrence > 50% are considered water
  const gsw = ee.Image('JRC/GSW1_4/GlobalSurfaceWater');
  const water = gsw.select('occurrence').gt(water_threshold).selfMask();

  // Create masks for river/water areas and land areas within the AOI
  const river_mask = water.updateMask(water).clip(aoi);
  const land_mask = water.unmask(0).not().selfMask().clip(aoi); // Everything not water

  // Reproject land and river masks to match image resolution for consistency
  const scale = 30; // Landsat resolution
  const crs = image.projection().crs();
  const river_mask_proj = river_mask.reproject(crs, null, scale);
  const land_mask_proj = land_mask.reproject(crs, null, scale);

  // Cloud mask from the Landsat image (0=clear, 1=cloudy)
  // We need to re-extract the cloud information from the `qa` band or the original masking.
  // The 'maskL5srCloudsAndShadows' function should return a cloud_mask band if we modified it.
  // For simplicity, let's assume the masked image now has its mask representing clear pixels.
  // So, where the image is masked, it's cloudy.
  const cloud_pixel = image.mask().not(); // 1 where originally masked (cloudy), 0 where clear.

  // Calculate valid pixel counts for land and river regions
  const landPixels = await cloud_pixel.updateMask(land_mask_proj).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).values().get(0).getInfo();

  const riverPixels = await cloud_pixel.updateMask(river_mask_proj).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).values().get(0).getInfo();

  if (landPixels === 0 || riverPixels === 0) {
    console.log(`Valid land pixels: ${landPixels}, Valid river pixels: ${riverPixels}`);
    console.log("No valid pixels remaining for land or river areas after masking.");
    console.log("C2");
    return;
  }

  // 4. Calculation - Mean cloud cover over land and river
  const cloudOverLand = await cloud_pixel.updateMask(land_mask_proj).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).values().get(0).getInfo();

  const cloudOverRiver = await cloud_pixel.updateMask(river_mask_proj).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).values().get(0).getInfo();

  // 5. Validation & Final Answer
  if (cloudOverLand === null || cloudOverRiver === null || isNaN(cloudOverLand) || isNaN(cloudOverRiver)) {
    console.log("Calculation resulted in null or NaN values for cloud cover.");
    console.log(`Cloud over Land: ${cloudOverLand}, Cloud over River: ${cloudOverRiver}`);
    console.log("C3");
    return;
  }

  console.log(`Cloud cover over Land: ${cloudOverLand * 100:.2f}% (Valid Pixels: ${landPixels})`);
  console.log(`Cloud cover over River: ${cloudOverRiver * 100:.2f}% (Valid Pixels: ${riverPixels})`);

  if (cloudOverLand > cloudOverRiver) {
    console.log("A");
  } else {
    console.log("B");
  }
}

/**
 * Function to mask clouds and cloud shadows from Landsat 5 SR images.
 * Uses the pixel_qa band to identify cloudy and cloud shadow pixels.
 */
function maskL5srCloudsAndShadows(image) {
  const qa = image.select('pixel_qa');

  // Bits 3 and 5 are cloud and cloud shadow, respectively.
  const cloudBitMask = 1 << 3;
  const cloudShadowBitMask = 1 << 5;

  // Both flags should be set to 0 for clear conditions.
  const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
    .and(qa.bitwiseAnd(cloudShadowBitMask).eq(0));

  return image.updateMask(mask).select(['B1', 'B2', 'B3', 'B4', 'B5', 'B7']); // Return only spectral bands
}

/**
 * Function to mask clouds from Landsat 5 TOA images using simple thresholding.
 * This is a less robust cloud mask for TOA data but helps identify major clouds.
 */
function maskL5toaCloudsAndShadows(image) {
  // Simple cloud detection using brightness and temperature for TOA
  const cloud_prob_threshold = 0.2; // Adjust as needed
  const cloud_band_sum = image.select(['B1', 'B2', 'B3', 'B4', 'B5', 'B7']).reduce(ee.Reducer.sum());
  const thermal_band = image.select('B6'); // Thermal band

  // Clouds are usually bright and cold.
  // This is a very basic cloud mask and might not be perfect.
  const cloud1 = cloud_band_sum.gt(ee.Image(0.6)); // Brightness threshold
  const cloud2 = thermal_band.lt(ee.Image(290)); // Coldness threshold (e.g., < 290K)

  const cloudMask = cloud1.and(cloud2).not(); // Clear pixels are where not cloud1 and not cloud2

  return image.updateMask(cloudMask).select(['B1', 'B2', 'B3', 'B4', 'B5', 'B7']);
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

